def sequence(n,k,title,events,caption):
    names=[]
    for a,b,_ in events:
        for name in (a,b):
            if name not in names:names.append(name)
    positions={name:80+i*740/max(1,len(names)-1) for i,name in enumerate(names)}
    height=100+len(events)*55;body=''
    for name,x in positions.items():
        body+=text(x,25,name,18,13)+f'<path d="M{x} 40V{height-15}" stroke="#a5b9ad" stroke-dasharray="4 5"/>'
    for i,(a,b,label) in enumerate(events):
        y=70+i*55;start=positions[a];end=positions[b];direction=1 if end>start else -1
        body+=f'<path d="M{start} {y}H{end-direction*7}" stroke="#3978a8" stroke-width="1.5"/><path d="M{end-direction*7} {y-4}L{end} {y}L{end-direction*7} {y+4}" fill="none" stroke="#3978a8"/>'+text((start+end)/2,y-10,label,45,11)
    return shell(n,0,k,title,body,caption,'Follow explicit message ordering and locate the acknowledgment or effect boundary.',height=height)


def plates(unit):
    n=unit['n'];html='';coverage=[]
    if n==1:return '',[]
    rows=MODELS[n]
    assert len(rows)==len(unit['illustrations']),(n,len(rows),len(unit['illustrations']))
    for k,(title,spec) in enumerate(zip(unit['illustrations'],rows),1):
        kind,data,caption,*rest=spec
        if kind=='special':visual=special(n,0,k,data)
        elif kind=='sequence':visual=sequence(n,k,title,data,caption)
        elif kind=='flow':visual=flow(n,0,k,title,data,caption,rest[0] if rest else False)
        elif kind=='snap':visual=snapshots(n,0,k,title,data,caption)
        elif kind=='bars':visual=bars(n,0,k,title,data,caption,rest[0] if rest else 'illustrative values')
        elif kind=='waterfall':visual=waterfall(n,0,k,title,data,caption)
        elif kind=='matrix':
            body,height=matrix_body(data);visual=shell(n,0,k,title,body,caption,'Compare the stated dimensions under one explicit contract.',height)
        elif kind=='queue':
            body='<path d="M100 30V245H820" stroke="#738087" fill="none"/>'
            points=[]
            for i in range(10,96,5):
                rho=i/100;w=.01/(1-rho);points.append((100+rho*700,245-w*1000))
            body+='<polyline points="'+' '.join(f'{x},{y}' for x,y in points)+'" fill="none" stroke="#3978a8" stroke-width="2"/>'
            body+=text(450,282,'Utilization rho: 0 → 1',size=13)+text(150,22,'Mean residence ms',size=12,anchor='start')+text(720,62,'At 95%: 200 ms',size=12)
            visual=shell(n,0,k,title,body,caption,'Queueing can dominate near a modeled capacity ceiling; this is calculated theory, not a benchmark.',310)
        elif kind=='tree':
            body=box(330,20,240,65,'Slow useful operation','caution')
            for x,label in [(40,'CPU executing?'),(330,'Waiting on resource?'),(620,'Wrong work or fan-out?')]:body+=box(x,150,240,80,label)+f'<path d="M450 85L{x+120} 150" stroke="#3978a8" fill="none"/>'
            visual=shell(n,0,k,title,body,caption,'Each branch is a hypothesis requiring profiling, traces, and workload evidence.',270)
        elif kind=='pyramid':
            body=''
            for i,(label,w) in enumerate([('End-to-end journey',210),('Boundary / contract',390),('Real integration',570),('Local invariant',750)]):
                x=450-w/2;y=25+i*55;body+=f'<rect x="{x}" y="{y}" width="{w}" height="50" fill="{["#eee8f4","#e4eee8","#edf2e8","#d8e9df"][i]}" stroke="#a8bdac"/>'+text(450,y+31,label,size=14)
            visual=shell(n,0,k,title,body,caption,'Test scope and feedback cost differ; choose by the failure evidence needed.',270)
        else:raise ValueError(kind)
        assert visual is not None,(n,k,kind)
        FIGURES[-1]['chapter']=unit['id'];FIGURES[-1]['essential_title']=title
        coverage.append(dict(required=title,figure=FIGURES[-1]['id'],status='available'))
        html+=visual
    return html,coverage
